from pathlib import Path

def gravar_3_linhas(caminho):
    linhas = ['Python', 'CSV', 'JSON']
    arquivo = Path(caminho)
    arquivo.write_text('\n'.join(linhas) + '\n', encoding='utf-8')
    return arquivo.read_text(encoding='utf-8').splitlines()

